/// <summary>
/// The MobCountOrderType is an extension of the MobOrder class, and parent class to all count order classes.
/// </summary>
abstract class MobCountOrderType extends MobOrder implements TFMOrderTypeInterface
{

}

Method.Source:
public static TFMOrderListResponseElement generateResponse(TFMRequestFiltersElement _filters, str _scannedValue)
{
    ListEnumerator				lEnum           = new DictClass(className2Id(classStr(MobCountOrderType))).extendedBy(true).getEnumerator();
    MobCountOrderType			typeCls;
    DictClass					dc;
    Map							returnMap = new Map(Types::string, Types::Record);
    MapEnumerator				mEnum;
    int							i = 1;
    TFMOrderListResponseElement	response = TFMOrderListResponseElement::Construct(MobConstants::Count());
    while (lEnum.moveNext())
    {

        dc = new DictClass(lEnum.current());
        if (dc == null)
        {
            continue;
        }
        typeCls = dc.makeObject() as MobCountOrderType;
        returnMap = MobHelper::mergeMaps(typeCls.getHeaderRecords(_filters, _scannedValue), returnMap);

    }
    response.mergeRecordMap(returnMap);

    return response;

}
